    or (
      academy_id = public.current_user_academy_id()
      and public.current_user_role() in (
        'academy_owner', 'academy_admin', 'center_admin', 'head_coach', 'coach'
      )
    )
  );

create policy event_results_staff_update on public.event_results
  for update using (
    public.is_super_admin()
    or (
      academy_id = public.current_user_academy_id()
      and public.current_user_role() in (
        'academy_owner', 'academy_admin', 'center_admin', 'head_coach', 'coach'
      )
    )
  )
  with check (
    public.is_super_admin()
    or (
      academy_id = public.current_user_academy_id()
      and public.current_user_role() in (
        'academy_owner', 'academy_admin', 'center_admin', 'head_coach', 'coach'
      )
    )
  );

create policy event_results_admin_delete on public.event_results
  for delete using (
    public.is_super_admin()
    or (academy_id = public.current_user_academy_id() and public.has_admin_or_higher())
  );

-- Audit hooks ---------------------------------------------------------------

create trigger trg_audit_events
  after insert or update or delete on public.events
  for each row execute function public.write_audit_log();

create trigger trg_audit_event_registrations
  after insert or update or delete on public.event_registrations
  for each row execute function public.write_audit_log();

create trigger trg_audit_event_results
  after insert or update or delete on public.event_results
  for each row execute function public.write_audit_log();

-- ============================================================================
-- Storage bucket for generated certificate PDFs.
-- Layout: <academy_id>/<event_id>/<student_id>.pdf
-- Bucket is private; reads are governed by an RLS policy that checks
-- whether the caller can see the result row.
-- ============================================================================

insert into storage.buckets (id, name, public)
values ('certificates', 'certificates', false)
on conflict (id) do nothing;

create policy "certificates_member_read"
  on storage.objects
  for select
  to authenticated
  using (
    bucket_id = 'certificates'
    and (
      public.is_super_admin()
      or (storage.foldername(name))[1] = public.current_user_academy_id()::text
    )
  );

-- Writes only via service role (Edge Function). No INSERT/UPDATE/DELETE
-- policies for app-level callers.
